create table public."crs_consent"("consent_key" text not null,"relationship_key" text not null,"consent_scope" text not null,"consent_state" text not null,"consent_source" text not null,"evidence_ref" text,"granted_at" timestamp with time zone,"withdrawn_at" timestamp with time zone,"metadata" jsonb default '{}'::jsonb not null,"created_at" timestamp with time zone default now() not null);
create table public."measures_persistence_state"("persistence_key" text not null,"process_key" text not null,"oar2_key" text not null,"environment_key" text not null,"object_key" text not null,"object_type" text not null,"governed_state" jsonb default '{}'::jsonb not null,"source_sha256" text,"evidence" jsonb default '{}'::jsonb not null,"custody" jsonb default '{}'::jsonb not null,"lineage" jsonb default '{}'::jsonb not null,"standing" text not null,"next_permitted_transition" text,"persisted_by" text default 'registrar'::text not null,"persisted_at" timestamp with time zone default now() not null,"updated_at" timestamp with time zone default now() not null);
alter table public."crs_consent" add constraint "crs_consent_pkey" PRIMARY KEY (consent_key);
alter table public."crs_consent" add constraint "crs_consent_relationship_key_fkey" FOREIGN KEY (relationship_key) REFERENCES crs_relationship(relationship_key);
alter table public."crs_consent" enable row level security;grant select,insert,update,delete on public."crs_consent" to service_role;
alter table public."measures_persistence_state" add constraint "measures_persistence_state_environment_key_object_key_key" UNIQUE (environment_key, object_key);
alter table public."measures_persistence_state" add constraint "measures_persistence_state_pkey" PRIMARY KEY (persistence_key);
alter table public."measures_persistence_state" enable row level security;grant select,insert,update,delete on public."measures_persistence_state" to service_role;